__global__ void grouped_two_cholesky_64(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch
) {
    constexpr int N = 64;
    constexpr int LD = 65;
    constexpr int MATRICES_PER_BLOCK = 2;
    __shared__ float storage[MATRICES_PER_BLOCK * N * LD];
    __shared__ float inverse[MATRICES_PER_BLOCK];
    const int group = threadIdx.x / N;
    const int lane = threadIdx.x % N;
    const int matrix = static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + group;
    const bool active = matrix < batch;
    float* tile = storage + group * N * LD;

    if (active) {
        const long long base = static_cast<long long>(matrix) * N * N;
        const float* src = input + base;
        #pragma unroll
        for (int row = 0; row < N; ++row) {
            tile[row * LD + lane] = row >= lane
                ? src[row * N + lane]
                : 0.0f;
        }
    }
    __syncthreads();

    float row_values[N];
    #pragma unroll
    for (int col = 0; col < N; ++col) {
        row_values[col] = active ? tile[lane * LD + col] : 0.0f;
    }
    register_cholesky_step_64<0>(
        row_values, tile, inverse, group, lane, active
    );

    if (active) {
        const long long base = static_cast<long long>(matrix) * N * N;
        float* dst = output + base;
        #pragma unroll
        for (int row = 0; row < N; ++row) {
            dst[row * N + lane] = tile[row * LD + lane];
        }
    }
}

__device__ __forceinline__ void n128_group_sync() {
    if (threadIdx.x < 448) {
        asm volatile("bar.sync 1, 448;" ::: "memory");
    } else {
        asm volatile("bar.sync 2, 448;" ::: "memory");
    }
}

__device__ __forceinline__ int n128_block_tile_offset(
    int block_row,
    int block_col
) {
    return (block_row * (block_row + 1) / 2 + block_col) * 16 * 16;
}

__device__ __forceinline__ void factor_panel_16_warp(
    float* tile,
    int panel,
    int local_tid
) {
    const int lane = local_tid % 32;
    const int panel_block = panel / 16;
    float* diagonal = tile + n128_block_tile_offset(
        panel_block, panel_block
    );
    if (lane < 16) {
        float row_values[16];
        #pragma unroll
        for (int col = 0; col < 16; ++col) {
            row_values[col] = lane >= col
                ? diagonal[lane * 16 + col]
                : 0.0f;
        }

        #pragma unroll
        for (int pivot = 0; pivot < 16; ++pivot) {
            float value = row_values[pivot];
            #pragma unroll
            for (int col = 0; col < pivot; ++col) {
                const float pivot_value = __shfl_sync(
                    0x0000ffff, row_values[col], pivot, 16
                );
                if (lane >= pivot) {
                    value = fmaf(-row_values[col], pivot_value, value);
                }
            }
            float inverse = 0.0f;
            if (lane == pivot) {
                const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
                row_values[pivot] = diagonal;
                inverse = 1.0f / diagonal;
            }
            inverse = __shfl_sync(0x0000ffff, inverse, pivot, 16);
            if (lane > pivot) {
                row_values[pivot] = value * inverse;
            }
        }

        #pragma unroll
        for (int col = 0; col < 16; ++col) {
            if (lane >= col) {
                diagonal[lane * 16 + col] = row_values[col];
            }
        }
    }
}

__device__ __forceinline__ void factor_panel_16(
    float* tile,
    int panel,
    int local_tid,
    bool matrix_active
) {
    if (matrix_active && local_tid / 32 == 0) {
        factor_panel_16_warp(tile, panel, local_tid);
    }
    n128_group_sync();
}

__device__ __forceinline__ void solve_panel_16(
    float* tile,
    int panel,
    int local_tid,
    bool matrix_active
) {
    constexpr int N = 128;
    constexpr int TEAM_WIDTH = 4;
    const int team = local_tid / TEAM_WIDTH;
    const int lane = local_tid % TEAM_WIDTH;
    const int stop = panel + 16;
    const int row = stop + team;
    if (matrix_active) {
        const bool row_active = row < N;
        const int panel_block = panel / 16;
        float* diagonal = tile + n128_block_tile_offset(
            panel_block, panel_block
        );
        float* panel_tile = row_active
            ? tile + n128_block_tile_offset(row / 16, panel_block)
            : tile;
        const int local_row = row % 16;
        float row_values[4];
        #pragma unroll
        for (int item = 0; item < 4; ++item) {
            row_values[item] = row_active
                ? panel_tile[
                    local_row * 16 + item * TEAM_WIDTH + lane
                ]
                : 0.0f;
        }
        #pragma unroll
        for (int pivot = 0; pivot < 16; ++pivot) {
            float dot = 0.0f;
            #pragma unroll
            for (int item = 0; item < 4; ++item) {
                const int col = item * TEAM_WIDTH + lane;
                if (col < pivot) {
                    dot = fmaf(
                        row_values[item],
                        diagonal[pivot * 16 + col],
                        dot
                    );
                }
            }
            dot += __shfl_down_sync(0xffffffff, dot, 2, TEAM_WIDTH);
            dot += __shfl_down_sync(0xffffffff, dot, 1, TEAM_WIDTH);
            float original = __shfl_sync(
                0xffffffff,
                row_values[pivot / TEAM_WIDTH],
                pivot % TEAM_WIDTH,
                TEAM_WIDTH
            );
            float solved = lane == 0
                ? (original - dot)
                    / diagonal[pivot * 16 + pivot]
                : 0.0f;
            solved = __shfl_sync(0xffffffff, solved, 0, TEAM_WIDTH);
            if (lane == pivot % TEAM_WIDTH) {
                row_values[pivot / TEAM_WIDTH] = solved;
            }
        }
        if (row_active) {
            #pragma unroll
            for (int item = 0; item < 4; ++item) {
                panel_tile[
                    local_row * 16 + item * TEAM_WIDTH + lane
                ] =
                    row_values[item];
            }
        }
    }
    n128_group_sync();
}

__device__ __forceinline__ void compensated_rankk_16(
    float* tile,
    int panel,
    int local_tid,
    bool matrix_active
) {
    constexpr int N = 128;
    constexpr int WARPS = 14;
    constexpr int MMA_M = 16;
    constexpr int MMA_N = 16;
    constexpr int MMA_K = 8;
    constexpr float RESIDUAL_SCALE = 32.0f;
    constexpr float INVERSE_RESIDUAL_SCALE = 1.0f / RESIDUAL_SCALE;
    const int warp = local_tid / 32;
    const int stop = panel + 16;
    const int tile_count = (N - stop) / MMA_M;
    const int panel_block = panel / MMA_M;
    const int stop_block = stop / MMA_M;
    if (matrix_active) {
        int ordinal = 0;
        for (int block_row = 0; block_row < tile_count; ++block_row) {
            for (int block_col = 0; block_col <= block_row; ++block_col) {
                if (ordinal % WARPS == warp) {
                    {
                wmma::fragment<
                    wmma::matrix_a, MMA_M, MMA_N, MMA_K,
                    wmma::precision::tf32, wmma::row_major
                > a_high;
                wmma::fragment<
                    wmma::matrix_a, MMA_M, MMA_N, MMA_K,
                    wmma::precision::tf32, wmma::row_major
                > a_scaled;
                wmma::fragment<
                    wmma::matrix_b, MMA_M, MMA_N, MMA_K,
                    wmma::precision::tf32, wmma::col_major
                > b_high;
                wmma::fragment<
                    wmma::matrix_b, MMA_M, MMA_N, MMA_K,
                    wmma::precision::tf32, wmma::col_major
                > b_scaled;
                wmma::fragment<
                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
                > high_product;
                wmma::fragment<
                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
                > scaled_product;
                wmma::fragment<
                    wmma::accumulator, MMA_M, MMA_N, MMA_K, float
                > accumulator;
                wmma::fill_fragment(high_product, 0.0f);
                wmma::fill_fragment(scaled_product, 0.0f);
                #pragma unroll
                for (int offset = 0; offset < 16; offset += MMA_K) {
                    wmma::load_matrix_sync(
                        a_high,
                        tile + n128_block_tile_offset(
                            stop_block + block_row, panel_block
                        ) + offset,
                        MMA_M
                    );
                    wmma::load_matrix_sync(
                        b_high,
                        tile + n128_block_tile_offset(
                            stop_block + block_col, panel_block
                        ) + offset,
                        MMA_N
                    );
                    #pragma unroll
                    for (int element = 0;
                         element < a_high.num_elements;
                         ++element) {
                        const float original = a_high.x[element];
                        const float high = wmma::__float_to_tf32(original);
                        a_high.x[element] = high;
                        a_scaled.x[element] = wmma::__float_to_tf32(
                            fmaf(RESIDUAL_SCALE, original - high, high)
                        );
                    }
                    #pragma unroll
                    for (int element = 0;
                         element < b_high.num_elements;
                         ++element) {
                        const float original = b_high.x[element];
                        const float high = wmma::__float_to_tf32(original);
                        b_high.x[element] = high;
                        b_scaled.x[element] = wmma::__float_to_tf32(
                            fmaf(RESIDUAL_SCALE, original - high, high)
                        );
                    }
                    wmma::mma_sync(
                        high_product, a_high, b_high, high_product
                    );
                    wmma::mma_sync(
                        scaled_product,
                        a_scaled,
                        b_scaled,
                        scaled_product
                    );
                }
                wmma::load_matrix_sync(
                    accumulator,
                    tile + n128_block_tile_offset(
                        stop_block + block_row,
                        stop_block + block_col
                    ),
                    MMA_N,
                    wmma::mem_row_major
                );
                #pragma unroll
                for (int element = 0;
                     element < accumulator.num_elements;
                     ++element) {
                    const float correction = (
                        scaled_product.x[element]
                        - high_product.x[element]
                    ) * INVERSE_RESIDUAL_SCALE;
                    accumulator.x[element] -=
                        high_product.x[element] + correction;
                }
                wmma::store_matrix_sync(
                    tile + n128_block_tile_offset(
                        stop_block + block_row,
                        stop_block + block_col
                    ),
                    accumulator,
                    MMA_N,
                    wmma::mem_row_major
                );
                    }
                }
                ++ordinal;
            }
        }
        if (warp == 0) {
            factor_panel_16_warp(tile, stop, local_tid);
        }
    }
    n128_group_sync();
}

__global__ void blocked_wmma16_cholesky_128(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch,
    int paired_blocks
) {
    constexpr int N = 128;
    constexpr int THREADS_PER_MATRIX = 448;
    constexpr int MATRICES_PER_BLOCK = 2;
    constexpr int BLOCK_TILE_ELEMENTS = 36 * 16 * 16;
    extern __shared__ float storage[];
    const int group = threadIdx.x / THREADS_PER_MATRIX;
    const int tid = threadIdx.x % THREADS_PER_MATRIX;
    const int block = static_cast<int>(blockIdx.x);
    const int matrix = block < paired_blocks
        ? block * MATRICES_PER_BLOCK + group
        : 2 * paired_blocks + block - paired_blocks
            + (group == 0 ? 0 : batch);
    const bool active = matrix < batch;
    float* tile = storage + group * BLOCK_TILE_ELEMENTS;
    const int base = matrix * N * N;
    const float* src = input + base;
    float* dst = output + base;
    if (active) {
        for (int vector = tid; vector < N * N / 4;
             vector += THREADS_PER_MATRIX) {
            const int row = vector / (N / 4);
            const int col = vector % (N / 4) * 4;
            if (row >= col) {
                float4 values = reinterpret_cast<const float4*>(src)[vector];
                if (row < col + 3) values.w = 0.0f;
                if (row < col + 2) values.z = 0.0f;
                if (row < col + 1) values.y = 0.0f;
                float* packed_tile = tile + n128_block_tile_offset(
                    row / 16, col / 16
                );
                *reinterpret_cast<float4*>(
                    packed_tile + (row % 16) * 16 + col % 16
                ) = values;
            }
        }
    }
    n128_group_sync();

    factor_panel_16(tile, 0, tid, active);
    #pragma unroll
    for (int panel = 0; panel < N; panel += 16) {
        if (panel + 16 < N) {
            solve_panel_16(tile, panel, tid, active);
            compensated_rankk_16(tile, panel, tid, active);
        }
    }

    if (active) {
        for (int vector = tid; vector < N * N / 4;
             vector += THREADS_PER_MATRIX) {
            const int row = vector / (N / 4);
            const int col = vector % (N / 4) * 4;
            if (row >= col) {
                const float* packed_tile = tile + n128_block_tile_offset(
                    row / 16, col / 16
                );
                float4 values = *reinterpret_cast<const float4*>(
                    packed_tile + (row % 16) * 16 + col % 16
                );
                if (row < col + 3) values.w = 0.0f;
                if (row < col + 2) values.z = 0.0f;
                if (row < col + 1) values.y = 0.0f;
                reinterpret_cast<float4*>(dst)[vector] = values;
            }
        }
    }
}

