torch::Tensor cholesky128_cuda(torch::Tensor input) {
    torch::Tensor output = cached_small_output(input, 128);
    constexpr int shared_bytes = 2 * 36 * 16 * 16 * sizeof(float);
    static const cudaError_t configured = cudaFuncSetAttribute(
